		// new root: children are original children + parent (if any)
		children := make([]*Tree, 0, len(tr.children)+1)
		children = append(children, tr.children...)
		if parent != nil {
			children = append(children, parent)
		}
		return &Tree{value: tr.value, children: children}
	}
	// recurse into children
	newChildren := make([]*Tree, 0, len(tr.children))
	for _, ch := range tr.children {
		if r := ch.fromPov(from, tr); r != nil {
			// hmm, need to be careful
		}
