package pov

type Tree struct {
	value    string
	children []*Tree
}

// New creates and returns a new Tree with the given root value and children.
func New(value string, children ...*Tree) *Tree {
	return &Tree{value: value, children: children}
}

// Value returns the value at the root of a tree.
func (tr *Tree) Value() string {
	return tr.value
}

// Children returns a slice containing the children of a tree.
// There is no need to sort the elements in the result slice,
// they can be in any order.
func (tr *Tree) Children() []*Tree {
	return tr.children
}

// String describes a tree in a compact S-expression format.
// This helps to make test outputs more readable.
// Feel free to adapt this method as you see fit.
func (tr *Tree) String() string {
	if tr == nil {
		return "nil"
	}
	result := tr.Value()
	if len(tr.Children()) == 0 {
		return result
	}
	for _, ch := range tr.Children() {
		result += " " + ch.String()
	}
	return "(" + result + ")"
}

// POV problem-specific functions

// FromPov returns the pov from the node specified in the argument.
// It returns nil if the tree does not contain a node with that value.
func (tr *Tree) FromPov(from string) *Tree {
	// Find the path from the root to the target node.
	// path[0] is the target, path[len(path)-1] is the root.
	var path []*Tree
	var find func(t *Tree) bool
	find = func(t *Tree) bool {
		if t.value == from {
			path = append(path, t)
			return true
		}
		for _, ch := range t.children {
			if find(ch) {
				path = append(path, t)
				return true
			}
		}
		return false
	}
	if !find(tr) {
		return nil
	}

	// Rebuild the tree bottom-up, starting from the root.
	// Each node on the path keeps its off-path children and gains
	// the already-rebuilt subtree (closer to the target) as a child.
	var result *Tree
	for i := len(path) - 1; i >= 0; i-- {
		node := path[i]
		children := make([]*Tree, 0, len(node.children)+1)
		for _, ch := range node.children {
			if i == 0 || ch != path[i-1] {
				children = append(children, ch)
			}
		}
		if result != nil {
			children = append(children, result)
		}
		result = &Tree{value: node.value, children: children}
	}
	return result
}

// PathTo returns the shortest path between two nodes in the tree.
// It returns nil if either node does not exist in the tree.
func (tr *Tree) PathTo(from, to string) []string {
	pov := tr.FromPov(from)
	if pov == nil {
		return nil
	}
	return pov.pathTo(to)
}

// pathTo returns the path from the root of the tree to the node
// with the given value, or nil if no such node exists.
func (tr *Tree) pathTo(to string) []string {
	if tr.value == to {
		return []string{tr.value}
	}
	for _, ch := range tr.Children() {
		if p := ch.pathTo(to); p != nil {
			return append([]string{tr.value}, p...)
		}
	}
	return nil
}
